const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(e=>obs.observe(e));const svg=document.querySelector('#network'),ns='http://www.w3.org/2000/svg',nodes=Array.from({length:25},(_,i)=>({a:i*2.4,r:65+(i%6)*32})),lines=[];for(let i=0;i<25;i++)for(let j=i+1;j<25;j++)if((i+j)%6===0){let el=document.createElementNS(ns,'line');el.setAttribute('stroke','#a8b7f5');el.setAttribute('opacity','.35');svg.append(el);lines.push([el,i,j])}const dots=nodes.map(()=>{let c=document.createElementNS(ns,'circle');c.setAttribute('r',4);c.setAttribute('fill','#c4ceff');svg.append(c);return c});const journey=document.querySelector('.journey');let previous=-1;function frame(){let y=scrollY,p=Math.max(0,Math.min(1,(y-journey.offsetTop)/(journey.offsetHeight-innerHeight)));if(!reduced)document.querySelector('#art').style.transform=`translateY(${Math.min(y*.05,30)}px) rotate(${Math.min(y*.003,3)}deg)`;let stage=matchMedia('(max-width:760px)').matches||reduced?0:Math.min(2,Math.floor(p*3));if(stage!==previous || window.danhauschLanguageChanged){previous=stage;window.danhauschLanguageChanged=false;let scenes=window.danhauschScenes();document.querySelector('#chapter').textContent=scenes[stage][0];document.querySelector('#journeyTitle').innerHTML=scenes[stage][1];document.querySelector('#journeyText').textContent=scenes[stage][2]}let coords=nodes.map((n,i)=>{let r=n.r*(1-p)+130*p,a=n.a+p*2;return [300+Math.cos(a)*r,300+Math.sin(a)*r]});lines.forEach(([el,i,j])=>{el.setAttribute('x1',coords[i][0]);el.setAttribute('y1',coords[i][1]);el.setAttribute('x2',coords[j][0]);el.setAttribute('y2',coords[j][1])});dots.forEach((el,i)=>{el.setAttribute('cx',coords[i][0]);el.setAttribute('cy',coords[i][1])})}addEventListener('scroll',()=>requestAnimationFrame(frame),{passive:true});frame();
// Hero lines: scroll-linked morph from tangled paths to ordered, parallel flows.
(()=>{const flow=document.getElementById('heroFlow');if(!flow)return;const ns='http://www.w3.org/2000/svg';const paths=[];const count=19;for(let i=0;i<count;i++){const path=document.createElementNS(ns,'path');path.setAttribute('stroke',i%4===0?'#e1e4ff':i%3===0?'#8398ee':'#a8b7f5');path.setAttribute('opacity',String(.27+(i%5)*.12));flow.append(path);paths.push(path)}const mix=(a,b,t)=>a+(b-a)*t;const ease=t=>t*t*(3-2*t);function draw(){const hero=document.getElementById('inicio');const track=hero.parentElement;const span=Math.max(1,track.offsetHeight-innerHeight);const progress=reduced?1:ease(Math.max(0,Math.min(1,(scrollY-track.offsetTop)/(span*.7))));flow.dataset.progress=progress.toFixed(3);for(let i=0;i<count;i++){const yy=65+i*31;const phase=i*1.73;const startY=yy+Math.sin(phase)*110;const cp1Y=yy+Math.cos(phase*1.3)*245;const cp2Y=yy+Math.sin(phase*2.1)*205;const endY=yy+Math.cos(phase*.77)*120;const d=`M 0 ${mix(startY,yy,progress).toFixed(1)} C 240 ${mix(cp1Y,yy-12,progress).toFixed(1)}, 580 ${mix(cp2Y,yy+12,progress).toFixed(1)}, 900 ${mix(endY,yy,progress).toFixed(1)}`;paths[i].setAttribute('d',d)}}let pending=false;addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;draw()})}},{passive:true});addEventListener('resize',draw);draw()})();
